import { cva, type VariantProps } from "class-variance-authority"

// Uses cn-badge-* tokens from style-force-ui.css.
// Angular-specific notes vs registry source (see DIVERGENCES.md):
// - Per-variant focus-visible:ring-{status}/20 omitted (WCAG 1.4.11 failure)
// - [&>svg]:fill-current added (Material Symbols are fill-based, not stroke)
export const badgeVariants = cva(
  "group/badge inline-flex h-5 w-fit shrink-0 items-center justify-center gap-1 overflow-hidden rounded-4xl border border-transparent px-2 py-0.5 text-xs font-medium tracking-wide whitespace-nowrap uppercase transition-all focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&>svg]:pointer-events-none [&>svg]:size-3.5! [&>svg]:fill-current",
  {
    variants: {
      variant: {
        default:
          "bg-primary text-primary-foreground [a]:hover:bg-primary-hover",
        secondary:
          "bg-secondary text-secondary-foreground [a]:hover:bg-primary-subtle",
        destructive: "bg-error-subtle text-error",
        warning: "bg-warning-subtle text-warning",
        success: "bg-success-subtle text-success",
        info: "bg-info-subtle text-info",
        "success-solid": "bg-success-solid text-on-success",
        "warning-solid":
          "bg-warning-solid text-on-warning dark:text-on-warning",
        "info-solid": "bg-info-solid text-on-info",
        "error-solid": "bg-destructive text-on-error",
        outline: "border-border text-foreground [a]:hover:bg-primary-subtle",
        ghost: "hover:bg-primary-subtle hover:text-foreground",
        link: "text-link underline-offset-4 hover:underline",
      },
    },
    defaultVariants: { variant: "default" },
  }
)

export type BadgeVariants = VariantProps<typeof badgeVariants>
export type BadgeVariant = NonNullable<BadgeVariants["variant"]>

export { BadgeComponent as Badge } from "./badge.component"
export {
  badgeVariants,
  type BadgeVariants,
  type BadgeVariant,
} from "./badge.variants"
